/*
 * A095344  Length of n-th string generated by a Kolakoski(9,1) rule starting
 *          with a(1)=1.
 * https://oeis.org/A095344
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(1)=a(2)=1; for n>1, a(n)=a(n-1)+4*a(n-2)-4*(-1)^n
 * Range:     u8 n <= 6, u16 n <= 12, u32 n <= 24, u64 n <= 48, u128 n <= 95,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    if (n <= 2) return (seq_t)1;
    seq_t a0 = (seq_t)1;  /* a(n-2) */
    seq_t a1 = (seq_t)1;  /* a(n-1) */
    for (idx_t i = 3; i <= n; ++i) {
        seq_t term = a1 + (seq_t)4 * a0;          /* a(n-1)+4*a(n-2) */
        if ((i & 1) == 0) { /* n even: subtract 4 */
            term -= (seq_t)4;
        } else {              /* n odd: add 4 */
            term += (seq_t)4;
        }
        a0 = a1;
        a1 = term;
    }
    return a1;
}
